public sealed class OverdueInvoices : Specification<Invoice>
{
    public OverdueInvoices(int customerId, DateOnly asOf)
    {
        Where(i => i.CustomerId == customerId);
        Where(i => !i.IsPaid && i.Due < asOf);
        Include(i => i.Lines);
        OrderBy(i => i.Due);
        ReadOnly();
    }
}

public sealed class GetOverdueHandler(IReadRepository<Invoice> invoices)
    : IQueryHandler<GetOverdue, IReadOnlyList<InvoiceModel>>
{
    public async Task<Result<IReadOnlyList<InvoiceModel>>> HandleAsync(
        GetOverdue query, CancellationToken cancellationToken)
        => await invoices.ListAsync(new OverdueInvoices(query.CustomerId, query.AsOf), cancellationToken);
}

// No SaveChanges in the handler: TransactionBehavior commits when a command succeeds.
